<template><view class="bank-panel"><text class="heading">对公转账</text><view v-if="error">{{error}}</view><template v-if="info"><view v-if="!info.settings.enabled&&!info.started" class="hint">商家尚未启用对公转账。</view><template v-else><view class="card"><view>户名：{{info.settings.companyName}}</view><view>开户行：{{info.settings.bankName}}</view><view selectable>账号：{{info.settings.accountNumber}}</view><text class="hint">请核对收款信息。提交凭证不代表到账，财务核验足额后才会发货。</text><button class="ui-button" v-if="!info.started" :disabled="busy" @click="start">选择对公转账</button></view><view v-if="info.started" class="card"><input v-model="payer" placeholder="转账户名"/><input v-model="amount" type="digit" placeholder="本次转账金额（元）"/><button class="ui-button" :disabled="busy" @click="choose">{{proof?'已上传凭证，点击重选':'上传转账凭证图片'}}</button><button class="ui-button" :disabled="busy||!proof" @click="submit">提交给财务核验</button></view></template><view v-for="r in info.receipts" :key="r.id" class="card"><view>{{states[r.status]}} · ¥{{money(r.amount)}}</view><view v-if="r.confirmed_amount">已核验 ¥{{money(r.confirmed_amount)}}</view><view v-if="r.note">{{r.note}}</view></view><view v-for="r in info.refunds" :key="'r'+r.id" class="card"><view>{{r.status==='confirmed'?'财务已确认退款':'待财务退回'}} ¥{{money(r.amount)}}</view><view>{{r.reason}}</view></view></template></view></template>
<script>
import {refreshOnTick} from '../services/panel-refresh'
import {request,money,notify,uploadTransferProof} from '../services/shop.js'
export default {mixins:[refreshOnTick()],props:{orderId:{required:true}},data(){return{info:null,error:'',payer:'',amount:'',proof:'',key:'',busy:false,states:{pending:'待核验',confirmed:'已确认到账',rejected:'请补充资料'}}},mounted(){this.load()},methods:{money,async load(){try{this.info=await request('/orders/'+this.orderId+'/bank');this.error='';this.$emit('ready',this.info.started)}catch(e){this.error=e.message}},async act(fn){if(this.busy)return;this.busy=true;try{await fn();await this.load();this.$emit('updated')}catch(e){notify(e)}finally{this.busy=false}},start(){this.act(()=>request('/orders/'+this.orderId+'/bank/start','POST',{}))},choose(){if(this.busy)return;uni.chooseImage({count:1,sizeType:['compressed'],success:r=>this.act(async()=>{this.proof=await uploadTransferProof(r.tempFilePaths[0]);this.key=''}),fail:e=>{if(!/cancel/i.test(e.errMsg||''))notify('选图失败，请重试')}})},submit(){this.act(async()=>{if(!/^\d+(\.\d{1,2})?$/.test(this.amount)||Number(this.amount)<=0)throw Error('请填写正确金额，最多两位小数');if(!this.key)this.key='bank_'+Date.now()+'_'+Math.random().toString(36).slice(2);await request('/orders/'+this.orderId+'/bank/receipts','POST',{payer:this.payer,amount:Math.round(Number(this.amount)*100),proof:this.proof,requestKey:this.key});this.proof='';this.key='';this.amount='';uni.showToast({title:'已提交，等待核验',icon:'none'})})}}}
</script>
<style scoped>
@import '../styles/component-base.css';
.bank-panel{margin:16px;font-size:16px}.heading{font-size:20px;font-weight:bold}.card{background:var(--shop-surface, #fdfeff);border-radius:12px;padding:16px;margin-top:12px;line-height:1.8;overflow-wrap:anywhere}.hint{display:block;color:var(--shop-ink, #28546c);font-size:14px}input{margin:10px 0;padding:12px;background:var(--shop-background, #f3f8fb)}button{margin-top:12px;background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c);font-size:16px}</style>
